    internal static async Task RunAsync()
    {
        foreach (var partial in new[] { false, true })
        {
            var body = JsonNode.Parse(Full)!;
            foreach (var metric in new[] { body["summary"]!, body["numbers"]![0]! })
            {
                metric["deviceAnalytics"]!["customerPlatforms"]![0]!["platform"] = partial ? "unknown" : "ar_device";
                if (!partial) continue;
                metric["deviceAnalytics"]!["complete"] = false;
                metric["deviceAnalytics"]!["measured"] = false;
                metric["deviceAnalytics"]!["customerMessages"] = null;
                metric["deviceAnalytics"]!["inventory"]!["truncated"] = true;
                metric["deviceAnalytics"]!["inventory"]!["observedAt"] = null;
                metric["recipientActivity"]!["complete"] = false;
                metric["recipientActivity"]!["droppedSignals"] = 2;
                metric["recipientActivity"]!["truncated"] = true;
                metric["conversationBreakdown"]!["complete"] = false;
                metric["conversationBreakdown"]!["droppedConversations"] = 3;
                metric["conversationBreakdown"]!["truncated"] = true;
                metric["conversationBreakdown"]!["rows"]![0]!["readRate"] = null;
                metric["conversationBreakdown"]!["rows"]![0]!["replyRate"] = 0;
            }
            foreach (var project in new[] { false, true })
                await Organization("GET", project ? "/platform/projects/" + Adoption41Fixtures.Project + "/analytics" : "/platform/analytics", null, Adoption41Fixtures.Envelope(body.ToJsonString(), false), async c =>
                {
                    var value = project ? (await c.Project(Adoption41Fixtures.Project).Analytics.GetAsync()).Data : (await c.Analytics.GetAsync()).Data;
                    var m = value.Summary!;
                    Check(m.DeviceAnalytics.CustomerPlatforms[0].Platform == (partial ? "unknown" : "ar_device") && m.DeviceAnalytics.Complete == !partial && m.DeviceAnalytics.Measured == !partial, "Analytics device facts");
                    if (partial) Check(m.DeviceAnalytics.CustomerMessages is null && m.RecipientActivity!.DroppedSignals == 2 && m.RecipientActivity.Truncated && m.ConversationBreakdown.DroppedConversations == 3 && m.ConversationBreakdown.Rows[0].ReadRate is null && m.ConversationBreakdown.Rows[0].ReplyRate == 0, "Partial metrics preserve unknown and zero");
                });
        }
        var optional = JsonNode.Parse(Full)!;
        optional["summary"]!.AsObject().Remove("recipientActivity"); optional["numbers"]![0]!.AsObject().Remove("recipientActivity");
        await Organization("GET", "/platform/analytics", null, Adoption41Fixtures.Envelope(optional.ToJsonString(), false), async c => Check((await c.Analytics.GetAsync()).Data.Summary!.RecipientActivity is null, "Optional activity omitted"));
        Console.WriteLine("PASS analytics41 organization and immutable Project full/partial/unknown/zero metrics");
    }
